def stock_into_godowns(apps, schema_editor):
    """Every branch gets a default godown, "Main Store", and its stock moves
    into it unchanged: one stock row per product per branch was the old shape,
    so each becomes that product's row in the branch's default godown."""
    Branch = apps.get_model('inventory', 'Branch')
    Godown = apps.get_model('inventory', 'Godown')
    Stock = apps.get_model('inventory', 'Stock')
    for branch in Branch.objects.all():
        godown = Godown.objects.filter(branch=branch, is_default=True).first()
        if godown is None:
            godown = Godown.objects.create(branch=branch, name='Main Store', kind='godown',
                                           is_default=True, is_active=True)
        Stock.objects.filter(branch=branch, godown__isnull=True).update(godown=godown)


